def solution(input_text):
    lines = input_text.strip().split('\n')
    idx = 0

    n, e = map(int, lines[idx].split())
    idx += 1

    hate_edges = []
    for _ in range(e):
        a, b = map(int, lines[idx].split())
        hate_edges.append((a, b))
        idx += 1

    trainer_wishes = []
    teams = set()
    T = 0
    num_trainers_per_list = []

    for i in range(n):
        li = int(lines[idx])
        idx += 1
        wishes = []
        for _ in range(li):
            wishes.append(int(lines[idx]))
            idx += 1
            teams.add(wishes[-1])
        trainer_wishes.append(wishes)
        T = max(T, max(wishes))

    T = max(teams) if teams else n + 1
    team_conference = [0] * (T + 1)
    team_to_trainers = defaultdict(list)
    for i in range(n):
        for team in trainer_wishes[i]:
            team_to_trainers[team].append(i)

    def assign_teams_assignment(assignment):
        hate_count = 0
        for a, b in hate_edges:
            conf_a = assignment[a]
            conf_b = assignment[b]
            if conf_a == 1 and conf_b == 2:
                hate_count += 1
        return hate_count

    initial_assignments = [0] * n
    for i in range(n):
        initial_assignments[i] = random.choice(trainer_wishes[i])

    team_conf = [0] * (T + 1)
    for team in teams:
        team_conf[team] = random.choice([1, 2])

    current_hate = 0
    for a, b in hate_edges:
        if team_conf[initial_assignments[a]] != team_conf[initial_assignments[b]]:
            current_hate += 1

    for i in range(300):
        improved = False
        for trainer in list(range(n)):
            cur_team = initial_assignments[trainer]
            cur_conf = team_conf[cur_team]
            best_team = cur_team
            best_conf = cur_conf
            new_hate = 0

            old_conf_a = team_conf[cur_team]
            old_conf_b = team_conf[initial_assignments[
                next(t for t in range(n) if t != trainer and initial_assignments[t] == cur_team)
            ] if trainer in team_to_trainers[cur_team] else 0]

            for team in trainer_wishes[trainer]:
                team_conf[team] = (old_conf_a if old_conf_a != cur_conf else (old_conf_b if old_conf_b != cur_conf else 3))
                new_hate = 0
                for a, b in hate_edges:
                    if (initial_assignments[a] != cur_team and team_conf[initial_assignments[a]] != team_conf[team]) or \
                       (initial_assignments[b] != cur_team and team_conf[initial_assignments[b]] != team_conf[team]):
                        new_hate += 1

                if new_hate > current_hate:
                    current_hate = new_hate
                    best_team = team
                    break

            if best_team != cur_team:
                team_conf[cur_team] = team_conf[best_team] if isinstance(best_team, int) else team_conf[cur_team]
                for t in range(n):
                    if initial_assignments[t] == cur_team:
                        initial_assignments[t] = best_team

    for team in teams:
        if team_conf[team] == 3:
            team_conf[team] = random.choice([1, 2])

    output = []
    for i in range(n):
        output.append(initial_assignments[i])
    output.append('\n')
    for t in range(1, T + 1):
        output.append(str(team_conf[t]))

    return ' '.join(map(str, output[:-1])) + '\n' + ', '.join(map(str, [int(x) for x in output.split('\n')[-1].split()]))

