    ops = []

    def f(x):
        while x % k == 0:
            x //= k
        return x

    target = 1

    @lru_cache(maxsize=None)
    def solve(current_numbers):
        if len(current_numbers) == 1:
            if current_numbers[0] == target:
                return []
            else:
                return None

        result = None
        for i in range(len(current_numbers)):
            for j in range(i + 1, len(current_numbers)):
                x = f(current_numbers[i] + current_numbers[j])
                new_numbers = current_numbers[:i] + current_numbers[i+1:j+1] + [x] + current_numbers[j+1:]
                sub_ops = solve(tuple(new_numbers))
                if sub_ops is not None:
                    result = [(current_numbers[i], current_numbers[j])] + sub_ops
                    break
            if result is not None:
                break
        return result

    result = solve(tuple(a))
    if result:
        for x, y in result:
            ops.append(f(x))
            ops.append(f(y))
        # This approach doesn't quite work because we need to track operations

    # Let's try a different backtracking approach with explicit state tracking
    ops = []

    def backtrack(current_ops, current_numbers):
        if len(current_numbers) == 1:
            if current_numbers[0] == target:
                return True
            return False

        # Sort to have consistent state
        sorted_nums = sorted(current_numbers)

        for i in range(len(sorted_nums)):
            for j in range(i + 1, len(sorted_nums)):
                x = sorted_nums[i]
                y = sorted_nums[j]
                if x % k == 0:
                    x = x // k
                    while x % k == 0:
                        x = x // k
                if y % k == 0:
                    y = y // k
                    while y % k == 0:
                        y = y // k

                new_val = x + y
                while new_val % k == 0:
                    new_val //= k

                new_numbers = []
                for idx, num in enumerate(current_numbers):
                    if idx == i or idx == j:
                        continue
                    new_numbers.append(num)
                new_numbers.append(new_val)

                if backtrack(current_ops + [(x, y)], sorted(new_numbers)):
                    ops.append(f"{x} {y}")
                    return True
        return False

    if backtrack([], a):
        out = ["YES"] + ops
        return '\n'.join(out)
    else:
        return "NO"

import bisect

def solution(input_str):
    lines = input_str.strip().split('\n')
    idx = 0
    try:
        t = int(lines[idx])
        idx += 1
    except:
        return ""

    results = []
    for _ in range(t):
        try:
            n_str = lines[idx]
            idx += 1
            if n_str is None:
                break
            n = int(n_str)

            if idx >= len(lines):
                break
            a = list(map(int, lines[idx].split()))
            idx += 1

            if n <= 1:
                results.append("0")
                continue
            elif n == 0:
                results.append("0")
                continue

            # Find longest non-decreasing subsequence using patience sorting approach
            # This tracks the minimum ending value for each subsequence length
            dp = []

            for x in a:
                pos = bisect.bisect_left(dp, x)
                if pos == len(dp):
                    dp.append(x)
                else:
                    dp[pos] = x

            # Elements we keep = length of longest non-decreasing subsequence
            # Operations needed = n - kept_elements
            max_kept = len(dp)
            results.append(str(n - max_kept))
        except Exception:
            break

    return '\n'.join(results)

