"""
Solution for the minimum enclosing sphere problem (1-center problem).
The problem asks us to find a point such that the maximum distance from this point to any planet is minimized.
"""

import math
from typing import List, Tuple

def dist_sq(p1: Tuple[int, int, int], p2: Tuple[int, int, int]) -> float:
    """Calculate squared Euclidean distance between two points."""
    return (p1[0] - p2[0])**2 + (p1[1] - p2[1])**2 + (p1[2] - p2[2])**2

def dist(p1: Tuple[int, int, int], p2: Tuple[int, int, int]) -> float:
    """Calculate Euclidean distance between two points."""
    return math.sqrt(dist_sq(p1, p2))

def mid(p1: Tuple[int, int, int], p2: Tuple[int, int, int]) -> Tuple[float, float, float]:
    """Calculate midpoint between two points."""
    return ((p1[0] + p2[0]) / 2.0, (p1[1] + p2[1]) / 2.0, (p1[2] + p2[2]) / 2.0)

def gaussian_elimination(matrix: List[List[float]], rhs: List[float]) -> List[float]:
    """Solve linear system using Gaussian elimination."""
    n = len(matrix)
    # Forward elimination
    for i in range(n):
        # Find pivot
        max_row = i
        for k in range(i + 1, n):
            if abs(matrix[k][i]) > abs(matrix[max_row][i]):
                max_row = k
        matrix[i], matrix[max_row] = matrix[max_row], matrix[i]
        rhs[i], rhs[max_row] = rhs[max_row], rhs[i]

        if abs(matrix[i][i]) < 1e-10:
            matrix[i] = [0.0] * n
            rhs[i] = 0.0
            continue

        # Eliminate
        for k in range(i + 1, n):
            if abs(matrix[i][i]) > 1e-10:
                factor = matrix[k][i] / matrix[i][i]
                for j in range(i, n):
                    matrix[k][j] -= factor * matrix[i][j]
                rhs[k] -= factor * rhs[i]

    # Back substitution
    solution = [0.0] * n
    for i in range(n - 1, -1, -1):
        if abs(matrix[i][i]) < 1e-10:
            solution[i] = 0.0
        else:
            solution[i] = rhs[i]
            for j in range(i + 1, n):
                solution[i] -= matrix[i][j] * solution[j]
            solution[i] /= matrix[i][i]

    return solution

def min_sphere_1(points: List[Tuple[int, int, int]]) -> Tuple[float, float, float, float]:
    """Minimum enclosing sphere for 1 point."""
    p = points[0]
    return p[0], p[1], p[2], 0.0

def min_sphere_2(p1: Tuple[int, int, int], p2: Tuple[int, int, int]) -> Tuple[float, float, float, float]:
    """Minimum enclosing sphere for 2 points (diameter)."""
    c = mid(p1, p2)
    r = dist(p1, p2) / 2.0
    return c[0], c[1], c[2], r

def min_sphere_3(p1: Tuple[int, int, int], p2: Tuple[int, int, int], p3: Tuple[int, int, int]) -> Tuple[float, float, float, float]:
    """Minimum enclosing sphere for 3 points."""
    if abs(dist_sq(p1, p2) - dist_sq(p1, p3) - dist_sq(p2, p3)) < 1e-10:
        # Collinear points
        max_d = max(dist(p1, p2), dist(p1, p3), dist(p2, p3))
        if dist(p1, p2) == max_d:
            return min_sphere_2(p1, p2)
        elif dist(p1, p3) == max_d:
