def solution(s):
    import sys
    from collections import deque

    lines = s.strip().split('\n')
    if len(lines) < 1:
        return "-1"

    n = int(lines[0])
    if n < 3:
        return "-1"

    centers = []
    for i in range(n):
        parts = lines[i+1].split()
        if len(parts) >= 2:
            centers.append((float(parts[0]), float(parts[1])))

    if len(centers) < 3:
        return "-1"

    # Generate all pairwise edges
    edges = []
    for i in range(n):
        for j in range(i+1, n):
            dx = centers[i][0] - centers[j][0]
            dy = centers[i][1] - centers[j][1]
            w = (dx*dx + dy*dy) ** 0.5 / 2.0
            edges.append((i, j, w))

    # Sort edges by weight desc for Maximum Spanning Tree
    edges.sort(key=lambda x: x[2], reverse=True)

    # Union-Find
    parent = list(range(n))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    # Build Maximum Spanning Tree
    mst_adj = [[] for _ in range(n)]
    num_tree_edges = 0
    tree_includes = set()

    for i, j, w in edges:
        if find(i) != find(j):
            parent[find(i)] = find(j)
            tree_includes.add((min(i,j), max(i,j)))
            mst_adj[i].append((j, w))
            mst_adj[j].append((i, w))
            num_tree_edges += 1
            if num_tree_edges == n - 1:
                break

    # BFS to find minimum weight path in MST
    def bfs_min_path(start, end):
        if start == end:
            return float('inf')
        visited = set()
        queue = deque([(start, float('inf'))])
        while queue:
            u, bottleneck = queue.popleft()
            if u == end:
                return bottleneck
            for v, w in mst_adj[u]:
                if v not in visited:
                    visited.add(v)
                    new_bottleneck = min(bottleneck, w) if bottleneck != float('inf') else w
                    queue.append((v, new_bottleneck))
        return float('inf')

    # Answer is maximum of:
    # 1. Minimum edge in MST (representes bottleneck of MST cycles)
    # 2. For each non-tree edge, min(weight, path_on_mst)

    mst_weights = [e[2] for e in edges if (min(e[0], e[1]), max(e[0], e[1])) in tree_includes]
    if mst_weights:
        mst_min = min(mst_weights)
    else:
        mst_min = 0

    ans = mst_min

    for i, j, w in edges:
        if (min(i,j), max(i,j)) not in tree_includes:
            path_min = bfs_min_path(i, j)
            cycle_min = min(w, path_min)
            ans = max(ans, cycle_min)

    return "%.6f" % ans

