def tokenize(s):
    """Tokenize the input string into numbers, operators, and parentheses."""
    tokens = []
    i = 0
    while i < len(s):
        if s[i] == ' ':
            i += 1
            continue
        if s[i] == '+':
            tokens.append('+')
            i += 1
        elif s[i] == '-':
            # Check for subtraction vs negative
            tokens.append('-')
            i += 1
        elif s[i] == '(':
            tokens.append('(')
            i += 1
        elif s[i] == ')':
            tokens.append(')')
            i += 1
        else:
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            tokens.append(s[i:j])
            i = j
    return tokens

