def is_valid_set_score(a, b, set_num):
    """Check if a set score is valid for given set number (0-indexed)."""
    # Both scores must be non-negative and different
    if a < 0 or b < 0 or a == b:
        return False

    # For first 4 sets: winner must score at least 25, with 2-point lead
    if set_num < 4:
        winner_score = max(a, b)
        loser_score = min(a, b)
        return winner_score >= 25 and (winner_score - loser_score) >= 2

    # For set 5: winner must score at least 15, with 2-point lead
    if set_num == 4:
        winner_score = max(a, b)
        loser_score = min(a, b)
        return winner_score >= 15 and (winner_score - loser_score) >= 2

    return False

def can_form_sets(total_a, total_b, set_winners, first_four_count):
    """
    Check if we can form the given winning sequences to produce total scores.
    set_winners is a binary list where True = Team A wins, False = Team B wins
    first_four_count is the number of sets that must be played with 25-point rule
    """
    n = len(set_winners)

    # Dynamic programming: can we form the required winning pattern?
    # dp[i] = list of possible (a_prefix, b_prefix) pairs at index i
    dp = {0: []}
    dp[0].append((0, 0))

    for i in range(n):
        new_dp = {}
        for (a_curr, b_curr) in dp[i]:
            winner = set_winners[i]

            # Try to find valid set scores for current position
            if winner:
                min_a = 25 if i < 4 else 15
                min_b = 14 if i < 4 else 14
                limit_b = (min_a if i < 4 else 15) - 2
                # We won't go too high to avoid brute force explosion
                max_b_check = min(total_b - b_curr, 1000)

                found_valid = False
                for a_val in range(min_a, min(max_b_check + 1 + limit_b, 100000)):
                    for b_val in range(min_b, min_a - 1):
                        if is_valid_set_score(a_val, b_val - min_b + min_b, i):
                            pass
                    for b_val in range(min_b, min(total_b - b_curr, 1000) + 1):
                        if is_valid_set_score(a_val, b_val, i):
                            new_key = (a_curr + a_val, b_curr + b_val)
                            if new_key not in new_dp:
                                new_dp[new_key] = []
                            new_dp[new_key].append((a_val, b_val))
                            found_valid = True
                    if found_valid:
                        break

        if not new_dp:
            return []

    return []

