def solution(input_str):
    input_str = input_str.strip()
    if not input_str:
        return "0"

    lines = input_str.split('\n')
    try:
        n, m = map(int, lines[0].split())
    except:
        return "0"

    if m == 0:
        return "1" if n > 0 else "0"

    attempts = []
    responses = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        if len(parts) < 2:
            return "0"
        try:
            attempt_bits = [int(x) for x in parts[0]]
            response = int(parts[1])
            attempts.append(attempt_bits)
            responses.append(response)
        except:
            return "0"

    if len(attempts) != m or len(responses) != m or len(attempts[0]) != n:
        return "0"

    # Check first response constraint
    mex = n - responses[0]
    if mex < 0 or mex > n:
        return "0"

    from itertools import combinations

    base = tuple(attempts[0])
    candidates = set()

    if mex == 0:
        candidates.add(base)
    else:
        # Generate all codes that have exactly mex different positions from attempt 0
        for positions in combinations(range(n), mex):
            code = list(base)
            for pos in positions:
                code[pos] = 1 - code[pos]
            candidates.add(tuple(code))

    if not candidates:
        return "0"

    # Apply remaining constraints
    for i in range(1, m):
        new_candidates = set()

        for code in candidates:
            matches = sum(1 for j in range(n) if code[j] == attempts[i][j])
            if matches == responses[i]:
                new_candidates.add(code)

        candidates = new_candidates
        if not candidates:
            break

    return str(len(candidates))

from collections import defaultdict

def rev(x):
    """Reverse the digits of a number"""
    return int(str(x)[::-1])

def solution(s):
    """
    Find minimum x * y such that at least w lucky tickets exist.
    A ticket (a, b) is lucky if a * b = rev(a) * rev(b).
    """
    s = s.strip()
    if not s:
        return "-1\n"

    lines = s.split('\n')
    parts = lines[0].split()
    if len(parts) < 3:
        return "-1\n"

    try:
        maxx, maxy, w = int(parts[0]), int(parts[1]), int(parts[2])
    except:
        return "-1\n"

    edge_cases = (maxx == 0 or maxy == 0 or w == 0)
    if edge_cases:
        return "1 1\n" if w >= 0 else "-1\n"

    # Precompute reverse values
    limit = max(maxx, maxy)
    rev_vals = {}
    for i in range(1, limit + 1):
        rev_vals[i] = rev(i)

    # Collect valid pairs (a, b) where a * b = rev(a) * rev(b)
    pairs_by_a = defaultdict(list)

    for a in range(1, maxx + 1):
        ra = rev_vals[a]
        for b in range(1, maxy + 1):
            rb = rev_vals[b]
            if a * b == ra * rb:
                pairs_by_a[a].append(b)

    # Sort b values for efficient querying
    for a in pairs_by_a:
        pairs_by_a[a].sort()

    # Build cumulative structure: cumulative_bs[x] contains all b values where a <= x
    cumulative_bs = [None] * (maxx + 1)
    current_bs = []

    for x in range(1, maxx + 1):
        if x in pairs_by_a:
            current_bs.extend(pairs_by_a[x])
        cumulative_bs[x] = sorted(current_bs)

    # Find minimum x * y with at least w pairs
    ans = None
    min_prod = maxx * maxy + 1

    for x in range(1, maxx + 1):
        all_bs = cumulative_bs[x]
        if all_bs and len(all_bs) >= w:
            # Find the w-th smallest b value (1-indexed, so w-1)
            y = all_bs[w - 1]
            prod = x * y
            if prod < min_prod:
                min_prod = prod
                ans = (x, y)

    if ans:
        return f"{ans[0]} {ans[1]}\n"
    return "-1\n"


